1	// Pure helpers that turn the rich-text composer's contentEditable HTML into a
2	// safe, deliverable mail body. No React, no DOM APIs — just string work — so it
3	// runs identically in the browser (the Composer) and under `node:test`.
4	//
5	// The security contract mirrors the rest of the mail client: NOTHING leaves the
6	// composer without going through `safeHtml` (lib/mail/render.ts), the same
7	// sanitiser the IMAP engine runs on inbound bodies. The composed HTML is
8	// attacker-influenceable (a user can paste anything), and this platform sends
9	// real mail, so the toolbar must never become an XSS vector in the recipient's
10	// client.
11	//
12	// Inline images: browsers paste images into a contentEditable as
13	// `data:image/…;base64,…` URIs. `safeHtml` deliberately neutralises ALL `data:`
14	// URLs (a `data:text/html` src is a script vector), so a pasted image would be
15	// silently blanked to `src="#"` if we handed it straight to the sanitiser.
16	// Instead we lift each raster data-image OUT of the HTML first, swap its `src`
17	// for a `cid:` reference, and hand the bytes back as inline attachments the send
18	// path attaches with that Content-ID. `cid:` is not a dangerous scheme, so it
19	// survives `safeHtml` untouched, and nodemailer assembles a multipart/related
20	// message every mail client renders inline. Anything that is NOT a base64 raster
21	// data-image (e.g. `data:text/html`, `data:image/svg+xml`) is left for
22	// `safeHtml` to neutralise — dropped on purpose, never delivered.
23	
24	import { safeHtml } from "@/lib/mail/render";
25	
26	export type InlineImage = {
27	  cid: string; // Content-ID, referenced as `src="cid:<cid>"`
28	  filename: string;
29	  contentType: string; // e.g. "image/png"
30	  contentBase64: string; // raw base64, no "data:*;base64," prefix
31	};
32	
33	// A raster image the browser is willing to inline. SVG is excluded on purpose:
34	// it can carry script, and an inline SVG attachment is a needless XSS surface.
35	const RASTER_SUBTYPES = new Set(["png", "jpeg", "jpg", "gif", "webp", "bmp"]);
36	
37	// <img … src="data:image/<subtype>;base64,<data>" …> in either quote style.
38	const DATA_IMG =
39	  /<img\b[^>]*?\ssrc\s*=\s*(["'])data:image\/([a-z0-9.+-]+);base64,([a-z0-9+/=\s]*)\1[^>]*>/gi;
40	
41	function extFor(subtype: string): string {
42	  const s = subtype.toLowerCase();
43	  if (s === "jpeg" || s === "jpg") return "jpg";
44	  if (s === "svg+xml") return "svg";
45	  return s.replace(/[^a-z0-9]/g, "") || "img";
46	}
47	
48	/**
49	 * Lift base64 raster data-images out of `html`, replacing each `src` with a
50	 * `cid:` reference and returning the extracted bytes. Non-raster / non-base64
51	 * data-images are left in place (to be neutralised later by `safeHtml`).
52	 */
53	export function extractInlineImages(html: string): { html: string; images: InlineImage[] } {
54	  const images: InlineImage[] = [];
55	  let n = 0;
56	
57	  const out = (html || "").replace(DATA_IMG, (tag: string, _q: string, subtype: string, b64: string) => {
58	    if (!RASTER_SUBTYPES.has(subtype.toLowerCase())) return tag; // safeHtml will handle it
59	    const clean = b64.replace(/\s+/g, "");
60	    if (!clean) return tag;
61	    n += 1;
62	    const cid = `nximg-${n}-${Math.random().toString(36).slice(2, 10)}@nxeon`;
63	    images.push({
64	      cid,
65	      filename: `image-${n}.${extFor(subtype)}`,
66	      contentType: `image/${subtype.toLowerCase() === "jpg" ? "jpeg" : subtype.toLowerCase()}`,
67	      contentBase64: clean,
68	    });
69	    // Swap ONLY this tag's src value; leave every other attribute intact.
70	    return tag.replace(/\ssrc\s*=\s*(["'])data:[^"']*\1/i, ` src="cid:${cid}"`);
71	  });
72	
73	  return { html: out, images };
74	}
75	
76	/**
77	 * The one entry point the Composer uses. Extracts inline images to `cid:`
78	 * references, then runs the composed HTML through `safeHtml`. The returned
79	 * `html` is safe to send as-is; `images` are the inline attachments the send
80	 * path must carry with matching Content-IDs.
81	 */
82	export function prepareComposedBody(rawHtml: string): { html: string; images: InlineImage[] } {
83	  const { html, images } = extractInlineImages(rawHtml || "");
84	  return { html: safeHtml(html), images };
85	}
86	
87	/**
88	 * Derive the plain-text alternative from the composer's own `innerText`. The
89	 * editor already gives us caret-accurate text with real newlines, so we only
90	 * normalise the non-breaking spaces contentEditable inserts and trim the tail.
91	 * Kept here so the plain part is produced the same way everywhere and testable.
92	 */
93	export function plainTextFromEditor(innerText: string): string {
94	  return (innerText || "")
95	    .replace(/ /g, " ")
96	    .replace(/[ \t]+\n/g, "\n")
97	    .replace(/\s+$/, "");
98	}
