1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import type { SendAttachment, SendPayload } from "@/lib/mail/types";
5	import { safeHtml } from "@/lib/mail/render";
6	import type { SignaturePlacement } from "@/lib/mail/signature";
7	import { prepareComposedBody, plainTextFromEditor } from "./compose-html";
8	import { Icon } from "./util";
9	
10	export type ComposeDraft = {
11	  mode: "new" | "reply" | "replyAll" | "forward";
12	  to: string;
13	  cc: string;
14	  subject: string;
15	  body: string; // plaintext the user edits
16	  quotedHtml?: string; // quoted original, appended below the reply
17	  signature?: string; // plain-text signature / fallback for the text part
18	  signatureHtml?: string; // sanitized rich-signature HTML for the HTML part
19	  signaturePlacement?: SignaturePlacement; // where the signature sits relative to quoted text
20	  inReplyToUid?: number;
21	  replyFolder?: string;
22	};
23	
24	// Attachment limits — mirrored server-side (the server re-validates and is the
25	// source of truth). Kept here only for fast, friendly client-side feedback.
26	const MAX_ATTACHMENTS = 10;
27	const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB
28	
29	// A file the user has attached, already read into base64 in the browser.
30	type Attachment = {
31	  id: string;
32	  filename: string;
33	  contentType: string;
34	  size: number; // decoded byte size
35	  contentBase64: string;
36	};
37	
38	function formatBytes(bytes: number): string {
39	  if (bytes < 1024) return `${bytes} B`;
40	  const kb = bytes / 1024;
41	  if (kb < 1024) return `${kb < 10 ? kb.toFixed(1) : Math.round(kb)} KB`;
42	  const mb = kb / 1024;
43	  return `${mb < 10 ? mb.toFixed(1) : Math.round(mb)} MB`;
44	}
45	
46	// Read a File into raw base64 (stripping the "data:*;base64," prefix).
47	function readFileBase64(file: File): Promise<string> {
48	  return new Promise((resolve, reject) => {
49	    const reader = new FileReader();
50	    reader.onerror = () => reject(new Error(`Could not read ${file.name}.`));
51	    reader.onload = () => {
52	      const result = String(reader.result || "");
53	      const comma = result.indexOf(",");
54	      resolve(comma >= 0 ? result.slice(comma + 1) : result);
55	    };
56	    reader.readAsDataURL(file);
57	  });
58	}
59	
60	export function Composer({
61	  draft,
62	  onClose,
63	  onSend,
64	}: {
65	  draft: ComposeDraft;
66	  onClose: () => void;
67	  onSend: (payload: SendPayload) => Promise<void>;
68	}) {
69	  const [to, setTo] = useState(draft.to);
70	  const [cc, setCc] = useState(draft.cc);
71	  const [showCc, setShowCc] = useState(!!draft.cc);
72	  const [subject, setSubject] = useState(draft.subject);
73	  const [sending, setSending] = useState(false);
74	  const [error, setError] = useState<string | null>(null);
75	  const [attachments, setAttachments] = useState<Attachment[]>([]);
76	  const [reading, setReading] = useState(false);
77	  const [dragging, setDragging] = useState(false);
78	  // The rich editor is a contentEditable region (inherently ref-driven). We
79	  // track only whether it is EMPTY so the placeholder can show — the authoritative
80	  // HTML is always read from the ref at submit time, never from React state, so
81	  // there is no controlled/uncontrolled reset to lose the customer's draft.
82	  const [editorEmpty, setEditorEmpty] = useState(!draft.body.trim());
83	
84	  const fileInputRef = useRef<HTMLInputElement>(null);
85	  const imageInputRef = useRef<HTMLInputElement>(null);
86	  const editorRef = useRef<HTMLDivElement>(null);
87	  const dragDepth = useRef(0); // ignore nested dragenter/dragleave events
88	
89	  // Seed the editor once from the draft's plaintext body (escaped, newlines →
90	  // <br>). Reply/forward drafts start with blank lines; "new" starts empty.
91	  useEffect(() => {
92	    const el = editorRef.current;
93	    if (!el) return;
94	    const seed = draft.body
95	      ? draft.body.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\n/g, "<br>")
96	      : "";
97	    el.innerHTML = seed;
98	    setEditorEmpty(!el.textContent?.trim() && !el.querySelector("img"));
99	    // Seed exactly once on mount — the ref is stable and never re-seeded.
100	    // eslint-disable-next-line react-hooks/exhaustive-deps
101	  }, []);
102	
103	  useEffect(() => {
104	    const onKey = (e: KeyboardEvent) => {
105	      if (e.key === "Escape" && !sending) onClose();
106	      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") void submit();
107	    };
108	    window.addEventListener("keydown", onKey);
109	    return () => window.removeEventListener("keydown", onKey);
110	    // eslint-disable-next-line react-hooks/exhaustive-deps
111	  }, [to, cc, subject, sending, attachments]);
112	
113	  function syncEmpty() {
114	    const el = editorRef.current;
115	    setEditorEmpty(!!el && !el.textContent?.trim() && !el.querySelector("img"));
116	  }
117	
118	  // Apply a formatting command to the current selection inside the editor.
119	  function format(command: string, value?: string) {
120	    editorRef.current?.focus();
121	    try {
122	      document.execCommand(command, false, value);
123	    } catch {
124	      /* execCommand is unavailable in some embeddings — degrade to plain text */
125	    }
126	    syncEmpty();
127	  }
128	
129	  // Insert a pasted/embedded image as a data: URI at the caret. It is converted
130	  // to an inline cid attachment by prepareComposedBody() at send time.
131	  function insertInlineImage(file: File) {
132	    if (file.size > MAX_ATTACHMENTS_TOTAL_BYTES) {
133	      setError(`Images must be under ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
134	      return;
135	    }
136	    const reader = new FileReader();
137	    reader.onload = () => {
138	      const url = String(reader.result || "");
139	      if (!url.startsWith("data:image/")) return;
140	      editorRef.current?.focus();
141	      try {
142	        document.execCommand("insertImage", false, url);
143	      } catch {
144	        /* ignore — nothing inserted */
145	      }
146	      syncEmpty();
147	    };
148	    reader.readAsDataURL(file);
149	  }
150	
151	  // Paste: images go inline; everything else keeps the browser's formatted paste
152	  // (sanitised at send). Formatted copy-paste is therefore preserved reasonably.
153	  function onEditorPaste(e: React.ClipboardEvent) {
154	    const items = Array.from(e.clipboardData?.items ?? []);
155	    const image = items.find((i) => i.kind === "file" && i.type.startsWith("image/"));
156	    if (image) {
157	      const file = image.getAsFile();
158	      if (file) {
159	        e.preventDefault();
160	        setError(null);
161	        insertInlineImage(file);
162	      }
163	    }
164	  }
165	
166	  const totalBytes = attachments.reduce((n, a) => n + a.size, 0);
167	
168	  // Read a batch of picked/dropped files, enforcing count + total-size caps.
169	  async function addFiles(files: FileList | File[]) {
170	    const list = Array.from(files);
171	    if (list.length === 0) return;
172	    setError(null);
173	
174	    let count = attachments.length;
175	    let running = totalBytes;
176	    const next: Attachment[] = [];
177	    setReading(true);
178	    try {
179	      for (const file of list) {
180	        if (count >= MAX_ATTACHMENTS) {
181	          setError(`You can attach up to ${MAX_ATTACHMENTS} files.`);
182	          break;
183	        }
184	        if (running + file.size > MAX_ATTACHMENTS_TOTAL_BYTES) {
185	          setError(`Attachments can total at most ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
186	          break;
187	        }
188	        try {
189	          const contentBase64 = await readFileBase64(file);
190	          next.push({
191	            id: `${Date.now()}-${count}-${Math.random().toString(36).slice(2, 8)}`,
192	            filename: file.name || "attachment",
193	            contentType: file.type || "application/octet-stream",
194	            size: file.size,
195	            contentBase64,
196	          });
197	          count += 1;
198	          running += file.size;
199	        } catch (e) {
200	          setError(e instanceof Error ? e.message : "Could not read a file.");
201	        }
202	      }
203	      if (next.length) setAttachments((prev) => [...prev, ...next]);
204	    } finally {
205	      setReading(false);
206	    }
207	  }
208	
209	  function removeAttachment(id: string) {
210	    setAttachments((prev) => prev.filter((a) => a.id !== id));
211	    if (error) setError(null);
212	  }
213	
214	  function onDrop(e: React.DragEvent) {
215	    e.preventDefault();
216	    dragDepth.current = 0;
217	    setDragging(false);
218	    if (e.dataTransfer?.files?.length) void addFiles(e.dataTransfer.files);
219	  }
220	
221	  const title =
222	    draft.mode === "new" ? "New message" : draft.mode === "forward" ? "Forward" : "Reply";
223	
224	  async function submit() {
225	    if (sending || reading) return;
226	    if (!to.trim()) {
227	      setError("Add at least one recipient.");
228	      return;
229	    }
230	    setError(null);
231	    setSending(true);
232	    try {
233	      const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
234	
235	      // Read the composed rich body straight from the editor DOM — never from
236	      // React state — then sanitise it and lift inline images out to cid:
237	      // attachments. `safeBody` is XSS-safe HTML; `inlineImages` are the
238	      // multipart/related parts the send path carries with matching Content-IDs.
239	      const rawHtml = editorRef.current?.innerHTML ?? "";
240	      const plainText = plainTextFromEditor(editorRef.current?.innerText ?? "");
241	      const { html: safeBody, images: inlineImages } = prepareComposedBody(rawHtml);
242	
243	      // Guard the combined attachment budget (files + inline images) before we
244	      // hand oversize data to the server. The server re-validates authoritatively.
245	      const inlineBytes = inlineImages.reduce((n, img) => n + Math.floor((img.contentBase64.length * 3) / 4), 0);
246	      if (totalBytes + inlineBytes > MAX_ATTACHMENTS_TOTAL_BYTES) {
247	        setError(`Message is too large — files and inline images must total under ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
248	        setSending(false);
249	        return;
250	      }
251	
252	      // Signature: prefer the sanitized rich-HTML signature; fall back to the
253	      // legacy plain-text one. `signatureHtml` is already sanitized server-side,
254	      // but we re-sanitize here as defence in depth.
255	      const sigPlain = draft.signature?.trim();
256	      const sigRichRaw = draft.signatureHtml?.trim();
257	      const sigRich = sigRichRaw ? safeHtml(sigRichRaw) : "";
258	      const sigText = sigPlain ? `\n\n-- \n${sigPlain}` : "";
259	      const sigHtml = sigRich
260	        ? `<br><br><div class="nx-sig">${sigRich}</div>`
261	        : sigPlain
262	          ? `<br><div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;line-height:1.6;color:#64748b">-- <br>${esc(sigPlain)}</div>`
263	          : "";
264	
265	      const userDiv = `<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:#1e293b">${safeBody}</div>`;
266	      const quoteHtml = draft.quotedHtml
267	        ? `<br><blockquote style="margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b">${draft.quotedHtml}</blockquote>`
268	        : "";
269	
270	      // Placement only matters when there IS a quote (replies/forwards). "above"
271	      // puts the signature between the reply and the quoted original; "below"
272	      // (default) puts it after everything.
273	      const above = draft.signaturePlacement === "above";
274	      const htmlBody = above ? userDiv + sigHtml + quoteHtml : userDiv + quoteHtml + sigHtml;
275	
276	      const outAttachments: SendAttachment[] = [
277	        ...attachments.map((a) => ({
278	          filename: a.filename,
279	          contentType: a.contentType,
280	          contentBase64: a.contentBase64,
281	        })),
282	        ...inlineImages.map((img) => ({
283	          filename: img.filename,
284	          contentType: img.contentType,
285	          contentBase64: img.contentBase64,
286	          cid: img.cid,
287	        })),
288	      ];
289	
290	      await onSend({
291	        to: to.trim(),
292	        cc: cc.trim() || undefined,
293	        subject: subject.trim() || "(no subject)",
294	        text: plainText + sigText,
295	        html: htmlBody,
296	        attachments: outAttachments.length ? outAttachments : undefined,
297	        inReplyToUid: draft.inReplyToUid,
298	        replyFolder: draft.replyFolder,
299	      });
300	      onClose();
301	    } catch (e) {
302	      setError(e instanceof Error ? e.message : "Failed to send. Please try again.");
303	      setSending(false);
304	    }
305	  }
306	
307	  return (
308	    <div className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4" role="dialog" aria-modal="true" aria-label={title}>
309	      <div
310	        className="glass relative flex h-[85vh] w-full max-w-2xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-auto sm:max-h-[85vh]"
311	        onClick={(e) => e.stopPropagation()}
312	        onDragEnter={(e) => {
313	          if (!e.dataTransfer?.types?.includes("Files")) return;
314	          e.preventDefault();
315	          dragDepth.current += 1;
316	          setDragging(true);
317	        }}
318	        onDragOver={(e) => {
319	          if (e.dataTransfer?.types?.includes("Files")) e.preventDefault();
320	        }}
321	        onDragLeave={() => {
322	          dragDepth.current = Math.max(0, dragDepth.current - 1);
323	          if (dragDepth.current === 0) setDragging(false);
324	        }}
325	        onDrop={onDrop}
326	      >
327	        {/* Drag-and-drop overlay */}
328	        {dragging && (
329	          <div className="pointer-events-none absolute inset-0 z-10 flex items-center justify-center bg-navy-950/80 backdrop-blur-sm">
330	            <div className="flex flex-col items-center gap-2 rounded-xl border-2 border-dashed border-brand-400/60 bg-white/[0.04] px-8 py-6 text-brand-200">
331	              <Icon.paperclip size={22} />
332	              <span className="text-sm font-medium">Drop files to attach</span>
333	            </div>
334	          </div>
335	        )}
336	
337	        {/* Header */}
338	        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
339	          <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
340	            <span className="text-brand-300"><Icon.compose size={16} /></span>
341	            {title}
342	          </h3>
343	          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
344	            <Icon.close size={16} />
345	          </button>
346	        </div>
347	
348	        {/* Fields */}
349	        <div className="flex-1 overflow-y-auto">
350	          <FieldRow label="To">
351	            <input
352	              autoFocus={draft.mode !== "reply" && draft.mode !== "replyAll"}
353	              value={to}
354	              onChange={(e) => setTo(e.target.value)}
355	              placeholder="name@example.com, another@example.com"
356	              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
357	            />
358	            {!showCc && (
359	              <button onClick={() => setShowCc(true)} className="ml-2 flex-none text-xs font-medium text-slate-500 hover:text-brand-300">
360	                Cc
361	              </button>
362	            )}
363	          </FieldRow>
364	
365	          {showCc && (
366	            <FieldRow label="Cc">
367	              <input
368	                value={cc}
369	                onChange={(e) => setCc(e.target.value)}
370	                placeholder="cc@example.com"
371	                className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
372	              />
373	            </FieldRow>
374	          )}
375	
376	          <FieldRow label="Subject">
377	            <input
378	              value={subject}
379	              onChange={(e) => setSubject(e.target.value)}
380	              placeholder="Subject"
381	              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
382	            />
383	          </FieldRow>
384	
385	          {/* Scoped styling for the editor: Tailwind's preflight strips list
386	              markers and margins, so restore them here, and keep pasted/inserted
387	              images from overflowing the composer. */}
388	          <style>{`
389	            .nx-mail-editor ul { list-style: disc; padding-left: 1.5rem; margin: 0.25rem 0; }
390	            .nx-mail-editor ol { list-style: decimal; padding-left: 1.5rem; margin: 0.25rem 0; }
391	            .nx-mail-editor li { margin: 0.125rem 0; }
392	            .nx-mail-editor img { max-width: 100%; height: auto; border-radius: 0.375rem; }
393	            .nx-mail-editor a { color: #a89aff; text-decoration: underline; }
394	          `}</style>
395	
396	          {/* Formatting toolbar */}
397	          <Toolbar onFormat={format} onPickImage={() => imageInputRef.current?.click()} disabled={sending} />
398	
399	          {/* Rich-text body. contentEditable is ref-driven; its HTML is read at
400	              submit time and never mirrored into React state, so a form-action
401	              re-render can't wipe the customer's draft. */}
402	          <div className="relative">
403	            {editorEmpty && (
404	              <span className="pointer-events-none absolute left-5 top-4 text-sm text-slate-600">Write your message…</span>
405	            )}
406	            <div
407	              ref={editorRef}
408	              contentEditable={!sending}
409	              suppressContentEditableWarning
410	              role="textbox"
411	              aria-multiline="true"
412	              aria-label="Message body"
413	              spellCheck
414	              onInput={syncEmpty}
415	              onPaste={onEditorPaste}
416	              data-nx-mail-editor
417	              className="nx-mail-editor min-h-[16rem] w-full resize-none bg-transparent px-5 py-4 text-sm leading-relaxed text-slate-100 outline-none"
418	            />
419	          </div>
420	
421	          {/* Hidden input for inline images inserted from the toolbar. */}
422	          <input
423	            ref={imageInputRef}
424	            type="file"
425	            accept="image/png,image/jpeg,image/gif,image/webp"
426	            className="hidden"
