306	/** Resolve the IMAP path of the mailbox's Sent folder (defaults to "Sent"). */
307	async function findSentPath(client: ImapFlow): Promise<string> {
308	  try {
309	    const list = await client.list();
310	    const sent = list.find((f) => folderRole(f.path, f.specialUse) === "sent");
311	    return sent?.path || "Sent";
312	  } catch {
313	    return "Sent";
314	  }
