334	/** Strip path separators, quotes and control chars from an attachment filename. */
335	function sanitizeAttachmentName(name?: string): string {
336	  if (!name) return "";
337	  const cleaned = Array.from(name)
338	    .filter((ch) => {
339	      const c = ch.codePointAt(0) ?? 0;
340	      if (c < 0x20 || c === 0x7f) return false; // control chars
341	      if (ch === '"' || ch === "\\" || ch === "/") return false;
342	      return true;
343	    })
344	    .join("");
345	  return cleaned.trim().slice(0, 200);
346	}
