411	/**
412	 * Send a message from the user's own mailbox over SMTP submission, append a copy
413	 * to Sent, and (for replies) thread it + flag the original \Answered.
414	 */
415	export async function sendMessage(
416	  payload: SendPayload,
417	  mailboxAddress?: string,
418	): Promise<{ ok: boolean; error?: string }> {
419	  const { user, cred, identity } = await resolveMailbox(mailboxAddress);
420	  enforceRateLimit(`mail:send:burst:${user.id}`, { max: 5, windowMs: 60 * 1000 });
421	  enforceRateLimit(`mail:send:${user.id}`, { max: 60, windowMs: 60 * 60 * 1000 });
422	
423	  const to = parseRecipients(payload.to);
424	  const cc = parseRecipients(payload.cc);
425	  const bcc = parseRecipients(payload.bcc);
426	  const invalid = [...to.invalid, ...cc.invalid, ...bcc.invalid];
427	  if (invalid.length) return { ok: false, error: `Invalid recipient(s): ${invalid.join(", ")}` };
428	  if (to.list.length === 0) return { ok: false, error: "Add at least one recipient." };
429	  if (!payload.subject?.trim() && !payload.text?.trim() && !payload.html?.trim()) {
430	    return { ok: false, error: "Nothing to send — add a subject or a message." };
431	  }
432	
433	  const decoded = decodeAttachments(payload.attachments);
434	  if (!decoded.ok) return { ok: false, error: decoded.error };
435	  const attachments = decoded.attachments;
436	
437	  try {
438	    // Look up threading headers when this is a reply.
439	    let inReplyTo: string | undefined;
440	    let references: string | undefined;
441	    if (payload.inReplyToUid && payload.replyFolder) {
442	      try {
443	        await withMailbox(cred, payload.replyFolder, async (client) => {
444	          const orig = await client.fetchOne(String(payload.inReplyToUid), { uid: true, envelope: true }, { uid: true });
445	          if (orig && orig.envelope?.messageId) {
446	            inReplyTo = orig.envelope.messageId;
447	            references = orig.envelope.messageId;
448	          }
449	          // Mark the message we're replying to as answered (best effort).
450	          try {
451	            await client.messageFlagsAdd(String(payload.inReplyToUid), ["\\Answered"], { uid: true });
452	          } catch {
453	            /* ignore */
454	          }
455	        });
456	      } catch {
457	        /* original not found — send without threading headers */
458	      }
459	    }
460	
461	    // Apply the saved sender identity.
462	    //
463	    // These three columns were written by the Identity panel and read by NOTHING:
464	    // the panel promised "Shown as the sender name on messages you send" and every
465	    // message still went out bare `from: cred.address` with no Reply-To, so a
466	    // customer who set a reply-to address had replies quietly go to the wrong
467	    // mailbox. Each field falls back to the previous behaviour when unset.
468	    //
469	    // Note `from` only changes the HEADER. nodemailer derives `built.envelope`
470	    // from the address part, so SMTP MAIL FROM stays the authenticated mailbox
471	    // and SPF/DKIM alignment (fixed today) is untouched.
472	    const displayName = identity.displayName?.trim();
473	    const replyTo = identity.replyTo?.trim();
474	    const organization = identity.organization?.trim();
475	
476	    // SANITISE the composed HTML server-side before it ships. The composer
477	    // already runs `safeHtml`, but this action is the last gate a body passes
478	    // through and must never trust the client — so an XSS vector or a malformed
479	    // body can't reach a recipient even if the client is bypassed. `safeHtml`
480	    // preserves `cid:` image refs and inline formatting; it only strips scripts,
481	    // event handlers and dangerous URL schemes.
482	    const safeBodyHtml = payload.html ? safeHtml(payload.html) : undefined;
483	
484	    // Map decoded attachments to nodemailer's shape, marking inline images
485	    // (those with a cid) so clients render them in place via multipart/related.
486	    const mailAttachments = attachments.map((a) =>
487	      a.cid
488	        ? { filename: a.filename, content: a.content, contentType: a.contentType, cid: a.cid, contentDisposition: "inline" as const }
489	        : { filename: a.filename, content: a.content, contentType: a.contentType },
490	    );
491	
492	    // Compile the message once so the exact bytes are both sent and saved to Sent.
493	    const composer = nodemailer.createTransport({ streamTransport: true, buffer: true, newline: "\r\n" });
494	    const built = await composer.sendMail({
495	      from: displayName ? { name: displayName, address: cred.address } : cred.address,
496	      replyTo: replyTo || undefined,
497	      to: to.list,
498	      cc: cc.list.length ? cc.list : undefined,
499	      bcc: bcc.list.length ? bcc.list : undefined,
500	      subject: payload.subject || "",
501	      text: payload.text || undefined,
502	      html: safeBodyHtml,
503	      attachments: mailAttachments.length ? mailAttachments : undefined,
504	      inReplyTo,
505	      references,
506	      headers: organization ? { Organization: organization } : undefined,
507	    });
508	    const raw = built.message as Buffer;
509	
510	    const smtp = nodemailer.createTransport({
511	      host: MAIL_SMTP_HOST,
512	      port: MAIL_SMTP_PORT,
513	      secure: MAIL_SMTP_PORT === 465,
514	      requireTLS: MAIL_SMTP_PORT !== 465,
515	      // Certificate verification stays ON — this session carries the customer's
516	      // mailbox password. See `mailTlsOptions` for the measurement behind it.
517	      tls: mailTlsOptions(),
518	      auth: { user: cred.address, pass: cred.password },
519	    });
520	    await smtp.sendMail({ envelope: built.envelope, raw });
521	
522	    // Save a copy to Sent (best effort — the message already went out).
523	    try {
524	      await withImap(cred, async (client) => {
525	        const sentPath = await findSentPath(client);
526	        await client.append(sentPath, raw, ["\\Seen"]);
527	      });
528	    } catch {
529	      /* Sent append failed — not fatal */
530	    }
531	
532	    return { ok: true };
533	  } catch (e) {
534	    return { ok: false, error: String((e as Error)?.message ?? e).slice(0, 300) };
535	  }
536	}
