542	/** Set or clear the \Seen or \Flagged flag on a message. */
543	export async function setFlag(
544	  folder: string,
545	  uid: number,
546	  flag: "seen" | "flagged",
547	  value: boolean,
548	  mailboxAddress?: string,
549	): Promise<void> {
550	  const { user, cred } = await resolveMailbox(mailboxAddress);
551	  enforceRateLimit(`mail:flag:${user.id}`, { max: 240, windowMs: 60 * 1000 });
552	  const imapFlag = flag === "seen" ? "\\Seen" : "\\Flagged";
553	  await withMailbox(cred, folder, async (client) => {
554	    if (value) await client.messageFlagsAdd(String(uid), [imapFlag], { uid: true });
555	    else await client.messageFlagsRemove(String(uid), [imapFlag], { uid: true });
556	  });
557	}
