559	/** Move a message from one folder to another. */
560	export async function moveMessage(
561	  folder: string,
562	  uid: number,
563	  toFolder: string,
564	  mailboxAddress?: string,
565	): Promise<void> {
566	  const { user, cred } = await resolveMailbox(mailboxAddress);
567	  enforceRateLimit(`mail:move:${user.id}`, { max: 120, windowMs: 60 * 1000 });
568	  await withMailbox(cred, folder, async (client) => {
569	    await client.messageMove(String(uid), toFolder, { uid: true });
570	  });
571	}
572	
573	/** Delete a message: move to Trash, or permanently expunge if already in Trash. */
574	export async function deleteMessage(folder: string, uid: number, mailboxAddress?: string): Promise<void> {
575	  const { user, cred } = await resolveMailbox(mailboxAddress);
576	  enforceRateLimit(`mail:delete:${user.id}`, { max: 120, windowMs: 60 * 1000 });
577	
578	  await withImap(cred, async (client) => {
579	    // Determine the Trash folder path.
580	    let trashPath = "Trash";
581	    try {
582	      const list = await client.list();
583	      const trash = list.find((f) => folderRole(f.path, f.specialUse) === "trash");
584	      if (trash) trashPath = trash.path;
585	    } catch {
586	      /* fall back to "Trash" */
587	    }
588	
589	    const inTrash = folderRole(folder) === "trash" || folder === trashPath;
590	    const lock = await client.getMailboxLock(folder);
591	    try {
592	      if (inTrash) {
593	        await client.messageDelete(String(uid), { uid: true });
594	      } else {
595	        await client.messageMove(String(uid), trashPath, { uid: true });
596	      }
597	    } finally {
598	      lock.release();
599	    }
600	  });
601	}
