111	export type SendPayload = {
112	  to: string; // comma-separated
113	  cc?: string;
114	  bcc?: string;
115	  subject: string;
116	  text?: string;
117	  html?: string;
118	  inReplyToUid?: number; // for replies (sets In-Reply-To / References)
119	  replyFolder?: string; // folder of the message being replied to
120	  attachments?: SendAttachment[]; // transient file attachments (not persisted)
121	};
