10	/**
11	 * Blank out the CONTENTS of every string / template literal, on top of
12	 * `stripComments`. Quotes and backticks are kept so the token stream still
13	 * parses by eye; only what is between them is erased.
14	 *
15	 * `${…}` interpolations inside a template literal are KEPT, because they are
16	 * executable code, not string content. Erasing them would hide exactly the
17	 * detail some tripwires exist to check — a rate-limit bucket keyed on
18	 * `` `x:${user.id}` `` versus one keyed on `` `x:${clientIp}` `` is the
19	 * difference between limiting an account and limiting a forgeable header, and
20	 * both collapse to the same blank if the interpolation goes with the text.
21	 *
22	 * WHY BOTH ARE NEEDED. `stripComments` deliberately preserves literals (there is
23	 * a test asserting exactly that), because plenty of tripwires need to read a
24	 * literal — "is MAIL_HOST still `mail.nxeon.cloud`?". But a tripwire asserting a
25	 * CALL is present must not match a mention of that call inside a string, and
26	 * this repo is full of such mentions: error copy, audit-log `action` values, and
27	 * doc strings that quote the very function being checked. Comments alone are not
28	 * enough here — `"Couldn't apply forwarding on the mail server"` and
29	 * `detail: "mailbox.suspend"` are executable code, and a naive grep is happy
30	 * with either.
31	 *
32	 * So: use `stripComments` when the assertion is ABOUT a literal's value, and
33	 * this when the assertion is about code SHAPE.
34	 */
35	export function stripCommentsAndStrings(src: string): string {
36	  const s = stripComments(src);
37	  const n = s.length;
38	  let out = "";
39	  let i = 0;
40	
41	  /** Consume the body of a literal opened by `quote` at `i`, appending to `out`. */
42	  const literal = (quote: string) => {
43	    out += quote;
44	    i++;
45	    while (i < n) {
46	      const c = s[i];
47	      if (c === "\\") {
48	        // Escapes are consumed whole so `\"` never closes the literal.
49	        i += 2;
50	        continue;
51	      }
52	      if (c === quote) break;
53	      // Newlines survive so line numbers in a failure still line up.
54	      if (c === "\n") out += "\n";
55	      if (quote === "`" && c === "$" && s[i + 1] === "{") {
