57	        // nested object/template inside it doesn't end it early.
58	        out += "${";
59	        i += 2;
60	        let depth = 1;
61	        while (i < n && depth > 0) {
62	          const d = s[i];
63	          if (d === "{") depth++;
64	          else if (d === "}") depth--;
65	          else if (d === '"' || d === "'" || d === "`") {
66	            literal(d); // nested literal — its own contents get blanked
67	            continue;
68	          }
69	          if (depth > 0) out += d;
70	          i++;
71	        }
72	        out += "}";
73	        continue;
74	      }
75	      i++;
76	    }
77	    if (i < n) out += s[i];
78	    i++;
79	  };
