133	export function stripComments(src: string): string {
134	  let out = "";
135	  let i = 0;
136	  const n = src.length;
137	  let quote: string | null = null;
138	  /** Last non-whitespace character emitted — decides `/` = regex vs. division. */
139	  let prev = "";
140	
141	  /** Positions where a `/` begins a regex literal rather than a division. */
142	  const REGEX_PRECEDERS = new Set(["", "(", ",", "=", ":", "[", "!", "&", "|", "?", "{", "}", ";", "+", "-", "*", "%", "~", "^", "<", ">", "\n"]);
143	  const REGEX_KEYWORDS = /\b(return|typeof|case|in|of|delete|void|instanceof|new|do|else|yield|await)\s*$/;
144	
145	  while (i < n) {
146	    const c = src[i];
147	    const next = src[i + 1];
148	
149	    if (quote) {
150	      out += c;
151	      if (c === "\\") {
152	        // Escape: copy the escaped character too, so `\"` never closes a string.
153	        if (i + 1 < n) out += src[i + 1];
154	        i += 2;
155	        continue;
156	      }
157	      if (c === quote) quote = null;
158	      i++;
159	      continue;
160	    }
161	
162	    if (c === '"' || c === "'" || c === "`") {
163	      quote = c;
164	      out += c;
165	      prev = c;
166	      i++;
167	      continue;
168	    }
169	
170	    // `//` and `/*` are ALWAYS comments in valid JS — a regex literal cannot
171	    // begin with an unescaped `/` or a `*`. So comments win unconditionally, and
172	    // the regex branch below only ever sees a genuine literal.
173	    if (c === "/" && next === "/") {
174	      while (i < n && src[i] !== "\n") i++;
175	      out += " ";
176	      continue;
177	    }
178	    if (c === "/" && next === "*") {
179	      i += 2;
180	      while (i < n && !(src[i] === "*" && src[i + 1] === "/")) i++;
181	      i += 2;
182	      out += " ";
183	      continue;
184	    }
185	
186	    // A regex literal must be consumed whole, or its escaped slashes (`\/\/` in
187	    // `/^https?:\/\//`) look like the start of a comment and eat the rest of the
188	    // line — silently deleting real code from everything asserted below.
189	    if (c === "/" && (REGEX_PRECEDERS.has(prev) || REGEX_KEYWORDS.test(out))) {
190	      out += c;
191	      i++;
192	      let inClass = false;
193	      for (; i < n; i++) {
194	        const r = src[i];
195	        out += r;
196	        if (r === "\\") {
197	          if (i + 1 < n) out += src[i + 1];
198	          i++;
199	          continue;
200	        }
201	        if (r === "[") inClass = true;
202	        else if (r === "]") inClass = false;
203	        else if (r === "/" && !inClass) {
204	          i++;
205	          break;
206	        } else if (r === "\n") {
207	          // Not a regex after all (unterminated) — stop rather than run away.
208	          i++;
209	          break;
210	        }
211	      }
212	      prev = "/";
213	      continue;
214	    }
215	
216	    out += c;
217	    if (!/\s/.test(c) || c === "\n") prev = c;
218	    i++;
219	  }
220	  return out;
221	}
