import type { MailAddress } from "@/lib/mail/types";

/* -------------------------------------------------------------------------- */
/* Presentation helpers shared across the mail UI                              */
/* -------------------------------------------------------------------------- */

/** Display name for an address: prefer the friendly name, fall back to the
 *  local part of the email (before the @). */
export function displayName(a?: MailAddress | null): string {
  if (!a) return "Unknown";
  if (a.name && a.name.trim()) return a.name.trim();
  const at = a.address.indexOf("@");
  return at > 0 ? a.address.slice(0, at) : a.address || "Unknown";
}

/** Up-to-two-letter initials from a name or address. */
export function initials(a?: MailAddress | null): string {
  const name = displayName(a);
  const parts = name.replace(/[^\p{L}\p{N} ]/gu, " ").trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

