 *  given sender always gets the same colour. Hues are pulled toward the violet /
 *  blue / cyan Nxeon range with a couple of warm accents for variety. */
const AVATAR_GRADIENTS = [
  "from-brand-500 to-accent-blue",
  "from-accent-blue to-brand-400",
  "from-brand-400 to-fuchsia-500",
  "from-accent-cyan to-accent-blue",
  "from-violet-500 to-brand-600",
  "from-sky-500 to-brand-500",
  "from-brand-600 to-violet-400",
  "from-emerald-500 to-accent-cyan",
  "from-rose-500 to-brand-500",
  "from-amber-500 to-rose-500",
];

export function avatarGradient(seed: string): string {
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
  return AVATAR_GRADIENTS[h % AVATAR_GRADIENTS.length];
}

