input.content:
// Pure recipient-chip parsing/validation for the mail composer. No React, no DOM
// APIs — just string work — so it runs identically in the browser (the chip
// inputs) and under `node:test`.
//
// The composer's To/Cc fields are chip inputs: the customer types an address and
// presses Enter/comma, or pastes a whole comma/space/newline-separated list, and
// each valid address becomes a removable chip. The send payload the server
// (`lib/actions-mail.ts` → `parseRecipients`) expects is a single
// comma-separated string, so `recipientsToField` re-joins the chips into exactly
// that shape. Validation is SOFT: a pasted list is split, the valid addresses
// become chips, and anything that isn't an address is handed back as `invalid`
// so the UI can surface it without dropping the customer's typing on the floor.

// Address SHAPE only (same lax rule the server uses). Real deliverability is the
// mail server's job; this just keeps obvious non-addresses out of the chips.
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** True when `addr` has the shape of an email address. */
export function isValidEmail(addr: string): boolean {
  return EMAIL_RE.test((addr || "").trim());
}

/** Pull the bare address out of a token, tolerating the `Name <addr>` form. */
export function extractAddress(token: string): string {
  const m = (token || "").match(/<([^>]+)>/);
  return (m ? m[1] : token).trim();
}

export type ParsedRecipients = { valid: string[]; invalid: string[] };

/**
 * Split a raw string into recipient tokens and classify each. Splitting happens
 * on commas, semicolons and newlines first (so a `Name <addr>` piece stays
 * whole), then a bracket-less piece is further split on whitespace so a
 * space-separated paste like `a@x.com b@y.com` still becomes two chips. Valid
 * addresses are de-duplicated case-insensitively, keeping first-seen order and
 * the original casing; everything else lands in `invalid`.
 */
export function parseRecipientInput(raw: string): ParsedRecipients {
  const pieces = (raw || "")
    .split(/[,;\n\r]+/)
    .map((s) => s.trim())
    .filter(Boolean);

  const tokens: string[] = [];
  for (const piece of pieces) {
    // A `Name <addr>` piece can contain spaces — keep it whole. A bracket-less
    // piece may itself be a space-separated list, so split it.
    if (piece.includes("<")) tokens.push(piece);
    else tokens.push(...piece.split(/\s+/).filter(Boolean));
  }

  const valid: string[] = [];
  const invalid: string[] = [];
  const seen = new Set<string>();
  for (const tok of tokens) {
    const addr = extractAddress(tok);
    if (isValidEmail(addr)) {
      const key = addr.toLowerCase();
      if (!seen.has(key)) {
        seen.add(key);
        valid.push(addr);
      }
    } else {
      invalid.push(tok);
    }
  }
  return { valid, invalid };
}

/**
 * Merge the addresses parsed out of `raw` into an existing chip list, de-duping
 * case-insensitively against what's already there. Returns the combined chips
 * and any tokens that weren't valid addresses (for the caller to keep in the
 * input buffer / flag).
 */
export function addRecipients(existing: string[], raw: string): { chips: string[]; invalid: string[] } {
  const { valid, invalid } = parseRecipientInput(raw);
  const seen = new Set(existing.map((e) => e.toLowerCase()));
  const chips = existing.slice();
  for (const v of valid) {
    const key = v.toLowerCase();
    if (!seen.has(key)) {
      seen.add(key);
      chips.push(v);
    }
  }
  return { chips, invalid };
}

/**
 * Serialise chips into the comma-separated string the send payload carries.
 * Mirrors what the server's `parseRecipients` splits back apart, so a chip list
 * round-trips to the exact addresses that get sent.
 */
export function recipientsToField(chips: string[]): string {
  return chips.join(", ");
}

// Pure helpers for sizing inline images in the composer. No React, no DOM — just
// the preset → CSS mapping — so the Composer and `node:test` agree on exactly
// what markup a chosen size produces.
//
// The chosen size is written onto the <img> as an inline `style` (a `width` in
// px, or `width: 100%` for "full") plus a matching `width` attribute. Both
// survive `prepareComposedBody` → `safeHtml` untouched — the sanitiser only
// strips scripts, event handlers and dangerous URL schemes, never `style`/`width`
// — so the image arrives in the recipient's client at the size the customer set.
// A `max-width: 100%` guard is always included so a large image can never blow
// out a narrow reading pane.

export type ImageSizePreset = "small" | "medium" | "large" | "full";

export const IMAGE_SIZE_PRESETS: ImageSizePreset[] = ["small", "medium", "large", "full"];

// Fixed pixel widths for the non-"full" presets. "full" scales to the container.
export const IMAGE_PRESET_WIDTHS: Record<Exclude<ImageSizePreset, "full">, number> = {
  small: 160,
  medium: 320,
  large: 480,
};

/** Short human label for a preset (toolbar buttons). */
export function imagePresetLabel(preset: ImageSizePreset): string {
  switch (preset) {
    case "small": return "S";
    case "medium": return "M";
    case "large": return "L";
    case "full": return "Full";
  }
}

/** The inline `style` value to set on an <img> for a preset. */
export function imageStyleForPreset(preset: ImageSizePreset): string {
  if (preset === "full") return "width: 100%; max-width: 100%; height: auto;";
  return `width: ${IMAGE_PRESET_WIDTHS[preset]}px; max-width: 100%; height: auto;`;
}

/** The `width` attribute value for a preset, or null for "full" (no fixed px). */
export function imageWidthAttrForPreset(preset: ImageSizePreset): string | null {
  return preset === "full" ? null : String(IMAGE_PRESET_WIDTHS[preset]);
}

/** The inline `style` value for an arbitrary pixel width (drag-resize), clamped. */
export function imageStyleForWidth(px: number): string {
  const w = Math.max(24, Math.round(px));
  return `width: ${w}px; max-width: 100%; height: auto;`;
}

"use client";

// Dashboard-layer compose provider.
//
// The composer used to live INSIDE the mail page (MailClient rendered <Composer>
// inline). That had two problems this provider fixes:
//
//  1. `position: fixed` on the composer was scoped to the mail client's own box,
//     not the viewport, because an ancestor carried a `backdrop-filter`
//     (`backdrop-blur-md`) — and a backdrop-filtered ancestor becomes the
//     containing block for its fixed descendants. Portalling the composer to
//     `document.body` (no filtered/transformed ancestor) makes `fixed` mean the
//     real viewport again, so the panel is ALWAYS visible regardless of scroll.
//
//  2. A composer rendered by a page is torn down the instant you navigate away,
//     losing an in-progress draft. This provider is mounted once at the shell
//     level (see components/portal/Shell.tsx), which the App Router keeps mounted
//     across route changes — so the composer, its draft, and a minimized dock
//     survive navigating to any other dashboard page until it's sent or discarded.
//
// It holds the single source of truth for the open draft and the minimized flag,
// owns the actual send (so a message can be sent from any page, not just the mail
// app), and renders the Composer through a portal. Mail pages drive it purely
// through `useCompose()`.

import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { SendPayload } from "@/lib/mail/types";
import { sendMessage } from "@/lib/actions-mail";
import { Composer, type ComposeDraft } from "./Composer";
import { Icon } from "./util";

type ComposeContextValue = {
  /** Open (or replace) the composer with a fully-built draft, un-minimized. */
  open: (draft: ComposeDraft) => void;
  minimize: () => void;
  restore: () => void;
  close: () => void;
  isOpen: boolean;
  isMinimized: boolean;
};

const ComposeContext = createContext<ComposeContextValue | null>(null);

/** Access the shell-level composer. Must be called under a <ComposeProvider>. */
export function useCompose(): ComposeContextValue {
  const ctx = useContext(ComposeContext);
  if (!ctx) throw new Error("useCompose must be used within a ComposeProvider");
  return ctx;
}

/** Fired on the window after a message is sent, so a mounted MailClient can
 *  refresh its Sent view without the provider knowing anything about it. */
export const MAIL_SENT_EVENT = "nxeon:mail-sent";

export function ComposeProvider({ children }: { children: React.ReactNode }) {
  const [draft, setDraft] = useState<ComposeDraft | null>(null);
  const [minimized, setMinimized] = useState(false);
  const [toast, setToast] = useState<string | null>(null);
  // Portals need a DOM target — only available after mount (never during SSR).
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);

  const open = useCallback((d: ComposeDraft) => {
    setDraft(d);
    setMinimized(false);
  }, []);
  const minimize = useCallback(() => setMinimized(true), []);
  const restore = useCallback(() => setMinimized(false), []);
  const close = useCallback(() => {
    setDraft(null);
    setMinimized(false);
  }, []);

  // The provider owns the send so it works from ANY page (the composer can be
  // sent after navigating away from the mail app). It re-uses the same server
  // action MailClient did; the mailbox to send from rides along on the draft.
  const handleSend = useCallback(async (payload: SendPayload, mailboxAddress?: string) => {
    const res = await sendMessage(payload, mailboxAddress);
    if (res && res.ok === false) throw new Error(res.error || "The mail server rejected the message.");
    setToast("Message sent.");
    try {
      window.dispatchEvent(new CustomEvent(MAIL_SENT_EVENT));
    } catch {
      /* SSR / no window — nothing to refresh */
    }
  }, []);

  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => {
    if (!toast) return;
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(null), 2600);
    return () => {
      if (toastTimer.current) clearTimeout(toastTimer.current);
    };
  }, [toast]);

  const value: ComposeContextValue = {
    open,
    minimize,
    restore,
    close,
    isOpen: !!draft,
    isMinimized: minimized,
  };

  return (
    <ComposeContext.Provider value={value}>
      {children}
      {mounted && draft
        ? createPortal(
            <Composer
              draft={draft}
              minimized={minimized}
              onMinimize={minimize}
              onRestore={restore}
              onClose={close}
              onSend={handleSend}
            />,
            document.body,
          )
        : null}
      {mounted && toast
        ? createPortal(
            <div className="pointer-events-none fixed bottom-4 left-1/2 z-[70] -translate-x-1/2" role="status" aria-live="polite">
              <div className="glass flex items-center gap-2 px-4 py-2.5 text-sm text-slate-100 shadow-2xl animate-fade-up">
                <span className="text-brand-300"><Icon.mail size={15} /></span>
                {toast}
              </div>
            </div>,
            document.body,
          )
        : null}
    </ComposeContext.Provider>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { SendAttachment, SendPayload } from "@/lib/mail/types";
import { safeHtml } from "@/lib/mail/render";
import type { SignaturePlacement } from "@/lib/mail/signature";
import { prepareComposedBody, plainTextFromEditor } from "./compose-html";
import { addRecipients, extractAddress, isValidEmail, parseRecipientInput, recipientsToField } from "./recipients";
import {
  IMAGE_SIZE_PRESETS,
  imagePresetLabel,
  imageStyleForPreset,
  imageWidthAttrForPreset,
  type ImageSizePreset,
} from "./compose-image-size";
import { Icon } from "./util";

export type ComposeDraft = {
  mode: "new" | "reply" | "replyAll" | "forward";
  to: string;
  cc: string;
  subject: string;
  body: string; // plaintext the user edits
  quotedHtml?: string; // quoted original, appended below the reply
  signature?: string; // plain-text signature / fallback for the text part
  signatureHtml?: string; // sanitized rich-signature HTML for the HTML part
  signaturePlacement?: SignaturePlacement; // where the signature sits relative to quoted text
  inReplyToUid?: number;
  replyFolder?: string;
  /** The mailbox to send from. The composer lives at the shell level now, so the
   *  active mailbox rides along on the draft instead of being read from the page. */
  sendMailboxAddress?: string;
};

// Attachment limits — mirrored server-side (the server re-validates and is the
// source of truth). Kept here only for fast, friendly client-side feedback.
const MAX_ATTACHMENTS = 10;
const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB

// A file the user has attached, already read into base64 in the browser.
type Attachment = {
  id: string;
  filename: string;
  contentType: string;
  size: number; // decoded byte size
  contentBase64: string;
};

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  const kb = bytes / 1024;
  if (kb < 1024) return `${kb < 10 ? kb.toFixed(1) : Math.round(kb)} KB`;
  const mb = kb / 1024;
  return `${mb < 10 ? mb.toFixed(1) : Math.round(mb)} MB`;
}

// Read a File into raw base64 (stripping the "data:*;base64," prefix).
function readFileBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error(`Could not read ${file.name}.`));
    reader.onload = () => {
      const result = String(reader.result || "");
      const comma = result.indexOf(",");
      resolve(comma >= 0 ? result.slice(comma + 1) : result);
    };
    reader.readAsDataURL(file);
  });
}

export function Composer({
  draft,
  minimized = false,
  onClose,
  onMinimize,
  onRestore,
  onSend,
}: {
  draft: ComposeDraft;
  /** When true, the full panel is hidden (but kept mounted so the draft, editor
   *  DOM and attachments survive) and a small docked bar is shown instead. */
  minimized?: boolean;
  onClose: () => void;
  onMinimize: () => void;
  onRestore: () => void;
  onSend: (payload: SendPayload, mailboxAddress?: string) => Promise<void>;
}) {
  // Recipients are chip inputs: `*Chips` hold committed addresses, `*Input` holds
  // what's being typed (also the home for tokens that weren't valid addresses).
  const [toChips, setToChips] = useState<string[]>(() => parseRecipientInput(draft.to).valid);
  const [toInput, setToInput] = useState("");
  const [ccChips, setCcChips] = useState<string[]>(() => parseRecipientInput(draft.cc).valid);
  const [ccInput, setCcInput] = useState("");
  const [showCc, setShowCc] = useState(!!draft.cc);
  const [subject, setSubject] = useState(draft.subject);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [reading, setReading] = useState(false);
  const [dragging, setDragging] = useState(false);
  // The rich editor is a contentEditable region (inherently ref-driven). We
  // track only whether it is EMPTY so the placeholder can show — the authoritative
  // HTML is always read from the ref at submit time, never from React state, so
  // there is no controlled/uncontrolled reset to lose the customer's draft.
  const [editorEmpty, setEditorEmpty] = useState(!draft.body.trim());
  // The floating size toolbar for a clicked inline image (viewport rect of the img).
  const [imgRect, setImgRect] = useState<DOMRect | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const editorRef = useRef<HTMLDivElement>(null);
  const toInputRef = useRef<HTMLInputElement>(null);
  const selectedImgRef = useRef<HTMLImageElement | null>(null);
  const dragDepth = useRef(0); // ignore nested dragenter/dragleave events

  // Seed the editor once from the draft's plaintext body (escaped, newlines →
  // <br>). Reply/forward drafts start with blank lines; "new" starts empty.
  useEffect(() => {
    const el = editorRef.current;
    if (!el) return;
    const seed = draft.body
      ? draft.body.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\n/g, "<br>")
      : "";
    el.innerHTML = seed;
    setEditorEmpty(!el.textContent?.trim() && !el.querySelector("img"));
    // Seed exactly once on mount — the ref is stable and never re-seeded.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Focus management: on open (and on every restore from minimized) put the caret
  // where the customer will type first — the To field for new/forward, the body
  // for a reply where the recipient is already filled in.
  useEffect(() => {
    if (minimized) return;
    const t = setTimeout(() => {
      if (draft.mode === "reply" || draft.mode === "replyAll") editorRef.current?.focus();
      else toInputRef.current?.focus();
    }, 0);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [minimized]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      // Esc minimizes (non-destructive — keeps the draft) rather than discarding.
      if (e.key === "Escape" && !sending && !minimized) {
        e.preventDefault();
        clearImgSelection();
        onMinimize();
      }
      if ((e.metaKey || e.ctrlKey) && e.key === "Enter" && !minimized) void submit();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [toChips, ccChips, toInput, ccInput, subject, sending, attachments, minimized]);

  function syncEmpty() {
    const el = editorRef.current;
    setEditorEmpty(!!el && !el.textContent?.trim() && !el.querySelector("img"));
  }

  /* ---- Recipient chips -------------------------------------------------- */
  function commitTo(raw: string) {
    const { chips, invalid } = addRecipients(toChips, raw);
    setToChips(chips);
    setToInput(invalid.join(", "));
    setError(invalid.length ? `Not a valid email: ${invalid.join(", ")}` : null);
  }
  function commitCc(raw: string) {
    const { chips, invalid } = addRecipients(ccChips, raw);
    setCcChips(chips);
    setCcInput(invalid.join(", "));
    setError(invalid.length ? `Not a valid email: ${invalid.join(", ")}` : null);
  }

  /* ---- Inline image sizing ---------------------------------------------- */
  function clearImgSelection() {
    selectedImgRef.current?.classList.remove("nx-img-selected");
    selectedImgRef.current = null;
    setImgRect(null);
  }

  function onEditorClick(e: React.MouseEvent) {
    const t = e.target as HTMLElement | null;
    if (t && t.tagName === "IMG") {
      if (selectedImgRef.current && selectedImgRef.current !== t) {
        selectedImgRef.current.classList.remove("nx-img-selected");
      }
      const img = t as HTMLImageElement;
      img.classList.add("nx-img-selected");
      selectedImgRef.current = img;
      setImgRect(img.getBoundingClientRect());
    } else {
      clearImgSelection();
    }
  }

  function applyImagePreset(preset: ImageSizePreset) {
    const img = selectedImgRef.current;
    if (!img) return;
    img.setAttribute("style", imageStyleForPreset(preset));
    const w = imageWidthAttrForPreset(preset);
    if (w) img.setAttribute("width", w);
    else img.removeAttribute("width");
    setImgRect(img.getBoundingClientRect());
    syncEmpty();
  }

  // Insert a pasted/embedded image as a data: URI at the caret. It is converted
  // to an inline cid attachment by prepareComposedBody() at send time.
  function insertInlineImage(file: File) {
    if (file.size > MAX_ATTACHMENTS_TOTAL_BYTES) {
      setError(`Images must be under ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const url = String(reader.result || "");
      if (!url.startsWith("data:image/")) return;
      editorRef.current?.focus();
      try {
        document.execCommand("insertImage", false, url);
      } catch {
        /* ignore — nothing inserted */
      }
      syncEmpty();
    };
    reader.readAsDataURL(file);
  }

  // Apply a formatting command to the current selection inside the editor.
  function format(command: string, value?: string) {
    editorRef.current?.focus();
    try {
      document.execCommand(command, false, value);
    } catch {
      /* execCommand is unavailable in some embeddings — degrade to plain text */
    }
    syncEmpty();
  }

  // Paste: images go inline; everything else keeps the browser's formatted paste
  // (sanitised at send). Formatted copy-paste is therefore preserved reasonably.
  function onEditorPaste(e: React.ClipboardEvent) {
    const items = Array.from(e.clipboardData?.items ?? []);
    const image = items.find((i) => i.kind === "file" && i.type.startsWith("image/"));
    if (image) {
      const file = image.getAsFile();
      if (file) {
        e.preventDefault();
        setError(null);
        insertInlineImage(file);
      }
    }
  }

  const totalBytes = attachments.reduce((n, a) => n + a.size, 0);

  // Read a batch of picked/dropped files, enforcing count + total-size caps.
  async function addFiles(files: FileList | File[]) {
    const list = Array.from(files);
    if (list.length === 0) return;
    setError(null);

    let count = attachments.length;
    let running = totalBytes;
    const next: Attachment[] = [];
    setReading(true);
    try {
      for (const file of list) {
        if (count >= MAX_ATTACHMENTS) {
          setError(`You can attach up to ${MAX_ATTACHMENTS} files.`);
          break;
        }
        if (running + file.size > MAX_ATTACHMENTS_TOTAL_BYTES) {
          setError(`Attachments can total at most ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
          break;
        }
        try {
          const contentBase64 = await readFileBase64(file);
          next.push({
            id: `${Date.now()}-${count}-${Math.random().toString(36).slice(2, 8)}`,
            filename: file.name || "attachment",
            contentType: file.type || "application/octet-stream",
            size: file.size,
            contentBase64,
          });
          count += 1;
          running += file.size;
        } catch (e) {
          setError(e instanceof Error ? e.message : "Could not read a file.");
        }
      }
      if (next.length) setAttachments((prev) => [...prev, ...next]);
    } finally {
      setReading(false);
    }
  }

  function removeAttachment(id: string) {
    setAttachments((prev) => prev.filter((a) => a.id !== id));
    if (error) setError(null);
  }

  function onDrop(e: React.DragEvent) {
    e.preventDefault();
    dragDepth.current = 0;
    setDragging(false);
    if (e.dataTransfer?.files?.length) void addFiles(e.dataTransfer.files);
  }

  const title =
    draft.mode === "new" ? "New message" : draft.mode === "forward" ? "Forward" : "Reply";

  async function submit() {
    if (sending || reading) return;

    // Flush any half-typed recipients into chips before validating/sending.
    const finalTo = addRecipients(toChips, toInput).chips;
    const finalCc = addRecipients(ccChips, ccInput).chips;
    setToChips(finalTo);
    setToInput("");
    setCcChips(finalCc);
    setCcInput("");

    if (finalTo.length === 0) {
      setError("Add at least one recipient.");
      return;
    }
    clearImgSelection();
    setError(null);
    setSending(true);
    try {
      const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

      // Read the composed rich body straight from the editor DOM — never from
      // React state — then sanitise it and lift inline images out to cid:
      // attachments. `safeBody` is XSS-safe HTML; `inlineImages` are the
      // multipart/related parts the send path carries with matching Content-IDs.
      const rawHtml = editorRef.current?.innerHTML ?? "";
      const plainText = plainTextFromEditor(editorRef.current?.innerText ?? "");
      const { html: safeBody, images: inlineImages } = prepareComposedBody(rawHtml);

      // Guard the combined attachment budget (files + inline images) before we
      // hand oversize data to the server. The server re-validates authoritatively.
      const inlineBytes = inlineImages.reduce((n, img) => n + Math.floor((img.contentBase64.length * 3) / 4), 0);
      if (totalBytes + inlineBytes > MAX_ATTACHMENTS_TOTAL_BYTES) {
        setError(`Message is too large — files and inline images must total under ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
        setSending(false);
        return;
      }

      // Signature: prefer the sanitized rich-HTML signature; fall back to the
      // legacy plain-text one. `signatureHtml` is already sanitized server-side,
      // but we re-sanitize here as defence in depth.
      const sigPlain = draft.signature?.trim();
      const sigRichRaw = draft.signatureHtml?.trim();
      const sigRich = sigRichRaw ? safeHtml(sigRichRaw) : "";
      const sigText = sigPlain ? `\n\n-- \n${sigPlain}` : "";
      const sigHtml = sigRich
        ? `<br><br><div class="nx-sig">${sigRich}</div>`
        : sigPlain
          ? `<br><div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;line-height:1.6;color:#64748b">-- <br>${esc(sigPlain)}</div>`
          : "";

      const userDiv = `<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:#1e293b">${safeBody}</div>`;
      const quoteHtml = draft.quotedHtml
        ? `<br><blockquote style="margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b">${draft.quotedHtml}</blockquote>`
        : "";

      // Placement only matters when there IS a quote (replies/forwards). "above"
      // puts the signature between the reply and the quoted original; "below"
      // (default) puts it after everything.
      const above = draft.signaturePlacement === "above";
      const htmlBody = above ? userDiv + sigHtml + quoteHtml : userDiv + quoteHtml + sigHtml;

      const outAttachments: SendAttachment[] = [
        ...attachments.map((a) => ({
          filename: a.filename,
          contentType: a.contentType,
          contentBase64: a.contentBase64,
        })),
        ...inlineImages.map((img) => ({
          filename: img.filename,
          contentType: img.contentType,
          contentBase64: img.contentBase64,
          cid: img.cid,
        })),
      ];

      await onSend(
        {
          to: recipientsToField(finalTo),
          cc: finalCc.length ? recipientsToField(finalCc) : undefined,
          subject: subject.trim() || "(no subject)",
          text: plainText + sigText,
          html: htmlBody,
          attachments: outAttachments.length ? outAttachments : undefined,
          inReplyToUid: draft.inReplyToUid,
          replyFolder: draft.replyFolder,
        },
        draft.sendMailboxAddress,
      );
      onClose();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to send. Please try again.");
      setSending(false);
    }
  }

  const hasRecipient = toChips.length > 0 || isValidEmail(extractAddress(toInput));

  // Minimized: hide the full panel (keeping it mounted so the draft, editor DOM
  // and attachments all persist) and show a compact docked bar.
  const dockLabel = subject.trim() || title;

  return (
    <>
      {/* Full composer. `pointer-events-none` on the fixed wrapper lets the page
          behind stay usable (so you can navigate while a draft is open); only the
          panel itself captures clicks. The wrapper carries NO filter/transform, so
          `fixed` resolves to the true viewport (the composer is portalled to
          <body>), keeping it visible no matter how far the page is scrolled. */}
      <div
        className={`fixed inset-0 z-[55] flex items-center justify-center p-0 sm:p-4 ${minimized ? "hidden" : ""} pointer-events-none`}
        role="dialog"
        aria-label={title}
      >
        {/* Scoped styling: restore list markers/margins Tailwind's preflight
            strips, keep images from overflowing, mark the selected image, and
            honour reduced-motion for the open/minimize animation. */}
        <style>{`
          .nx-mail-editor ul { list-style: disc; padding-left: 1.5rem; margin: 0.25rem 0; }
          .nx-mail-editor ol { list-style: decimal; padding-left: 1.5rem; margin: 0.25rem 0; }
          .nx-mail-editor li { margin: 0.125rem 0; }
          .nx-mail-editor img { max-width: 100%; height: auto; border-radius: 0.375rem; cursor: pointer; }
          .nx-mail-editor img.nx-img-selected { outline: 2px solid #a89aff; outline-offset: 1px; }
          .nx-mail-editor a { color: #a89aff; text-decoration: underline; }
          @media (prefers-reduced-motion: reduce) {
            .nx-compose-panel, .nx-compose-dock { animation: none !important; transition: none !important; }
          }
        `}</style>
        <div
          className="nx-compose-panel glass pointer-events-auto relative flex h-[85vh] max-h-[85vh] w-full max-w-2xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-auto"
          onClick={(e) => e.stopPropagation()}
          onDragEnter={(e) => {
            if (!e.dataTransfer?.types?.includes("Files")) return;
            e.preventDefault();
            dragDepth.current += 1;
            setDragging(true);
          }}
          onDragOver={(e) => {
            if (e.dataTransfer?.types?.includes("Files")) e.preventDefault();
          }}
          onDragLeave={() => {
            dragDepth.current = Math.max(0, dragDepth.current - 1);
            if (dragDepth.current === 0) setDragging(false);
          }}
          onDrop={onDrop}
        >
          {/* Drag-and-drop overlay */}
          {dragging && (
            <div className="pointer-events-none absolute inset-0 z-10 flex items-center justify-center bg-navy-950/80 backdrop-blur-sm">
              <div className="flex flex-col items-center gap-2 rounded-xl border-2 border-dashed border-brand-400/60 bg-white/[0.04] px-8 py-6 text-brand-200">
                <Icon.paperclip size={22} />
                <span className="text-sm font-medium">Drop files to attach</span>
              </div>
            </div>
          )}

          {/* Header */}
          <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
            <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
              <span className="text-brand-300"><Icon.compose size={16} /></span>
              {title}
            </h3>
            <div className="flex items-center gap-1">
              <button onClick={onMinimize} className="btn-ghost rounded-lg p-1.5" aria-label="Minimize" title="Minimize">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                  <path d="M5 19h14" />
                </svg>
              </button>
              <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Discard" title="Discard">
                <Icon.close size={16} />
              </button>
            </div>
          </div>

          {/* Fields */}
          <div
            className="flex-1 overflow-y-auto"
            onScroll={() => {
              if (selectedImgRef.current) setImgRect(selectedImgRef.current.getBoundingClientRect());
            }}
          >
            <ChipField
              label="To"
              chips={toChips}
              input={toInput}
              inputRef={toInputRef}
              disabled={sending}
              placeholder="name@example.com"
              onInput={setToInput}
              onCommit={commitTo}
              onRemove={(addr) => setToChips((prev) => prev.filter((c) => c !== addr))}
              onBackspaceEmpty={() => setToChips((prev) => prev.slice(0, -1))}
              trailing={
                !showCc ? (
                  <button onClick={() => setShowCc(true)} className="ml-2 flex-none text-xs font-medium text-slate-500 hover:text-brand-300">
                    Cc
                  </button>
                ) : null
              }
            />

            {showCc && (
              <ChipField
                label="Cc"
                chips={ccChips}
                input={ccInput}
                disabled={sending}
                placeholder="cc@example.com"
                onInput={setCcInput}
                onCommit={commitCc}
                onRemove={(addr) => setCcChips((prev) => prev.filter((c) => c !== addr))}
                onBackspaceEmpty={() => setCcChips((prev) => prev.slice(0, -1))}
              />
            )}

            <FieldRow label="Subject">
              <input
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                placeholder="Subject"
                className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
              />
            </FieldRow>

            {/* Formatting toolbar */}
            <Toolbar onFormat={format} onPickImage={() => imageInputRef.current?.click()} disabled={sending} />

            {/* Rich-text body. contentEditable is ref-driven; its HTML is read at
                submit time and never mirrored into React state, so a form-action
                re-render can't wipe the customer's draft. */}
            <div className="relative">
              {editorEmpty && (
                <span className="pointer-events-none absolute left-5 top-4 text-sm text-slate-600">Write your message…</span>
              )}
              <div
                ref={editorRef}
                contentEditable={!sending}
                suppressContentEditableWarning
                role="textbox"
                aria-multiline="true"
                aria-label="Message body"
                spellCheck
                onInput={syncEmpty}
                onPaste={onEditorPaste}
                onClick={onEditorClick}
                data-nx-mail-editor
                className="nx-mail-editor min-h-[16rem] w-full resize-none bg-transparent px-5 py-4 text-sm leading-relaxed text-slate-100 outline-none"
              />
            </div>

            {/* Hidden input for inline images inserted from the toolbar. */}
            <input
              ref={imageInputRef}
              type="file"
              accept="image/png,image/jpeg,image/gif,image/webp"
              className="hidden"
              onChange={(e) => {
                const f = e.target.files?.[0];
                if (f) insertInlineImage(f);
                e.target.value = "";
              }}
            />

            {draft.quotedHtml && (
              <p className="px-5 pb-4 text-xs text-slate-600">
                — the original message is quoted below your reply —
              </p>
            )}

            {/* Attachment chips */}
            {attachments.length > 0 && (
              <div className="border-t border-white/[0.06] px-5 py-3">
                <div className="mb-2 flex items-center justify-between text-[11px] text-slate-500">
                  <span>
                    {attachments.length} {attachments.length === 1 ? "attachment" : "attachments"}
                  </span>
                  <span>{formatBytes(totalBytes)} / {formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {attachments.map((a) => (
                    <span
                      key={a.id}
                      className="card flex max-w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-xs text-slate-200"
                      title={`${a.filename} — ${formatBytes(a.size)}`}
                    >
                      <span className="flex-none text-brand-300"><Icon.paperclip size={13} /></span>
                      <span className="max-w-[12rem] truncate">{a.filename}</span>
                      <span className="flex-none text-slate-500">{formatBytes(a.size)}</span>
                      <button
                        type="button"
                        onClick={() => removeAttachment(a.id)}
                        disabled={sending}
                        className="btn-ghost flex-none rounded p-0.5 text-slate-400 hover:text-white disabled:opacity-40"
                        aria-label={`Remove ${a.filename}`}
                      >
                        <Icon.close size={12} />
                      </button>
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Hidden file input driving the Attach button */}
          <input
            ref={fileInputRef}
            type="file"
            multiple
            className="hidden"
            onChange={(e) => {
              if (e.target.files?.length) void addFiles(e.target.files);
              e.target.value = ""; // allow re-selecting the same file
            }}
          />

          {/* Footer */}
          <div className="flex items-center justify-between gap-3 border-t border-white/[0.08] bg-white/[0.02] px-5 py-3">
            <div className="flex min-w-0 items-center gap-2">
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                disabled={sending || reading || attachments.length >= MAX_ATTACHMENTS}
                className="btn-ghost flex flex-none items-center gap-1.5 rounded-lg px-2 py-1.5 text-slate-300 disabled:opacity-40"
                title="Attach files"
