function FieldRow({ label, children, align = "center" }: { label: string; children: React.ReactNode; align?: "center" | "start" }) {
  return (
    <label className={`flex gap-3 border-b border-white/[0.06] px-5 py-2.5 ${align === "start" ? "items-start" : "items-center"}`}>
      <span className={`w-14 flex-none text-xs font-medium uppercase tracking-wide text-slate-500 ${align === "start" ? "pt-1.5" : ""}`}>{label}</span>
      <span className="flex flex-1 items-center">{children}</span>
    </label>
  );
}

/** A recipient chip input: committed addresses as removable pills plus a live
 *  text field. Enter / comma / semicolon (and blur) commit the buffer; Backspace
 *  on an empty buffer removes the last chip; paste splits a whole list. */
function ChipField({
  label,
  chips,
  input,
  inputRef,
  disabled,
  placeholder,
  onInput,
  onCommit,
  onRemove,
  onBackspaceEmpty,
  trailing,
}: {
  label: string;
  chips: string[];
  input: string;
  inputRef?: React.RefObject<HTMLInputElement | null>;
  disabled?: boolean;
  placeholder?: string;
  onInput: (v: string) => void;
  onCommit: (raw: string) => void;
  onRemove: (addr: string) => void;
  onBackspaceEmpty: () => void;
  trailing?: React.ReactNode;
}) {
  return (
    <label className="flex items-start gap-3 border-b border-white/[0.06] px-5 py-2.5">
      <span className="w-14 flex-none pt-1.5 text-xs font-medium uppercase tracking-wide text-slate-500">{label}</span>
      <span className="flex flex-1 flex-wrap items-center gap-1.5">
        {chips.map((addr) => (
          <span
            key={addr}
            className="inline-flex items-center gap-1 rounded-md border border-brand-400/25 bg-brand-500/10 py-0.5 pl-2 pr-1 text-xs text-slate-100"
          >
            <span className="max-w-[14rem] truncate">{addr}</span>
            <button
              type="button"
              onClick={() => onRemove(addr)}
              disabled={disabled}
              className="btn-ghost flex-none rounded p-0.5 text-slate-400 hover:text-white disabled:opacity-40"
              aria-label={`Remove ${addr}`}
            >
              <Icon.close size={11} />
            </button>
          </span>
        ))}
        <input
          ref={inputRef}
          value={input}
          disabled={disabled}
          onChange={(e) => onInput(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === "," || e.key === ";") {
              e.preventDefault();
              if (input.trim()) onCommit(input);
            } else if (e.key === "Backspace" && input === "" && chips.length > 0) {
              e.preventDefault();
              onBackspaceEmpty();
            }
          }}
          onBlur={() => {
            if (input.trim()) onCommit(input);
          }}
          onPaste={(e) => {
            const text = e.clipboardData?.getData("text") ?? "";
            if (/[,;\s]/.test(text)) {
              e.preventDefault();
              onCommit((input ? input + " " : "") + text);
            }
          }}
          placeholder={chips.length === 0 ? placeholder : ""}
          className="min-w-[8rem] flex-1 bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
        />
      </span>
      {trailing}
    </label>
  );
}

/** A single toolbar control. `onMouseDown`-prevents-default so the editor keeps
 *  its selection when the button is clicked. */
function TBtn({
  onClick,
  label,
  title,
  disabled,
  children,
}: {
  onClick: () => void;
  label: string;
  title: string;
  disabled?: boolean;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      aria-label={label}
      title={title}
      disabled={disabled}
      onMouseDown={(e) => e.preventDefault()}
      onClick={onClick}
      className="btn-ghost flex h-7 min-w-7 items-center justify-center rounded-md px-1.5 text-slate-300 hover:text-white disabled:opacity-40"
    >
      {children}
    </button>
  );
}

/** Rich-text formatting toolbar for the composer body. */
function Toolbar({
  onFormat,
  onPickImage,
  disabled,
}: {
  onFormat: (command: string, value?: string) => void;
  onPickImage: () => void;
  disabled?: boolean;
}) {
  return (
    <div className="flex flex-wrap items-center gap-0.5 border-b border-white/[0.06] bg-white/[0.02] px-3 py-1.5">
      <TBtn label="Bold" title="Bold (Ctrl/⌘+B)" disabled={disabled} onClick={() => onFormat("bold")}>
        <span className="text-sm font-bold">B</span>
      </TBtn>
      <TBtn label="Italic" title="Italic (Ctrl/⌘+I)" disabled={disabled} onClick={() => onFormat("italic")}>
        <span className="text-sm italic">I</span>
      </TBtn>
      <TBtn label="Underline" title="Underline (Ctrl/⌘+U)" disabled={disabled} onClick={() => onFormat("underline")}>
        <span className="text-sm underline">U</span>
      </TBtn>

      <span className="mx-1 h-4 w-px bg-white/10" />

      <select
        aria-label="Font size"
        title="Font size"
        disabled={disabled}
        defaultValue="3"
        onMouseDown={(e) => e.stopPropagation()}
        onChange={(e) => onFormat("fontSize", e.target.value)}
        className="h-7 rounded-md border border-white/10 bg-navy-900/60 px-1.5 text-xs text-slate-300 outline-none disabled:opacity-40"
      >
        <option value="2">Small</option>
        <option value="3">Normal</option>
        <option value="5">Large</option>
        <option value="6">Huge</option>
      </select>

      <label
        title="Text colour"
        className={`btn-ghost flex h-7 items-center gap-1 rounded-md px-1.5 text-slate-300 ${disabled ? "opacity-40" : "hover:text-white"}`}
      >
        <span className="text-sm font-semibold">A</span>
        <input
          type="color"
          aria-label="Text colour"
          disabled={disabled}
          defaultValue="#a89aff"
          onChange={(e) => onFormat("foreColor", e.target.value)}
          className="h-4 w-4 cursor-pointer border-0 bg-transparent p-0"
        />
      </label>

      <span className="mx-1 h-4 w-px bg-white/10" />

      <TBtn label="Bulleted list" title="Bulleted list" disabled={disabled} onClick={() => onFormat("insertUnorderedList")}>
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
          <path d="M8 6h13M8 12h13M8 18h13" />
          <circle cx="3.5" cy="6" r="1.2" fill="currentColor" stroke="none" />
          <circle cx="3.5" cy="12" r="1.2" fill="currentColor" stroke="none" />
          <circle cx="3.5" cy="18" r="1.2" fill="currentColor" stroke="none" />
        </svg>
      </TBtn>
      <TBtn label="Numbered list" title="Numbered list" disabled={disabled} onClick={() => onFormat("insertOrderedList")}>
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
          <path d="M10 6h11M10 12h11M10 18h11M4 4v4M3 8h2M3 14h2l-2 2.5h2" />
        </svg>
      </TBtn>

      <span className="mx-1 h-4 w-px bg-white/10" />

      <TBtn label="Insert image" title="Insert inline image" disabled={disabled} onClick={onPickImage}>
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <rect x="3" y="4" width="18" height="16" rx="2" />
          <circle cx="8.5" cy="9" r="1.5" />
          <path d="m21 16-5-5L5 21" />
        </svg>
      </TBtn>
    </div>
  );
}

