/* ---- Inbox auto-refresh (light polling) ------------------------------- */
// New mail used to appear only after a manual Refresh. Poll the current folder
// quietly and swap in the fresh page — without touching the open message or the
// compose draft (both live outside `list`). Held behind a stable ref so the
// interval binds once yet always reads current folder/page/search state, and
// PAUSED while the tab is hidden so a backgrounded tab never hammers IMAP.
const pollRef = useRef<() => void>(() => {});
pollRef.current = () => {
  if (typeof document !== "undefined" && document.hidden) return;
  if (listPending || refreshing) return; // don't collide with an in-flight load
  const path = resolvePath(selected);
  if (path === null) return; // virtual view (Snoozed) — nothing to poll
  const key = selected;
  const q = search;
  listMessages(path, key === STARRED ? 1 : page, q || undefined, activeAddress)
    .then((res) => {
      // Discard if the user navigated to another folder/search while in flight.
      if (key !== selected || q !== search) return;
      if (key === STARRED) {
        const flagged = res.messages.filter((m) => m.flagged);
        setList({ messages: flagged, total: flagged.length, page: 1, pageSize: res.pageSize });
      } else {
        setList(res);
      }
    })
    .catch(() => {
      /* transient IMAP hiccup — the next tick tries again, no toast */
    });
};
useEffect(() => {
  const id = setInterval(() => pollRef.current(), 45_000);
  // Refresh immediately when the tab regains focus (it was paused while hidden).
  const onVis = () => {
    if (!document.hidden) pollRef.current();
  };
  document.addEventListener("visibilitychange", onVis);
  return () => {
    clearInterval(id);
    document.removeEventListener("visibilitychange", onVis);
  };
}, []);

