import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { stripCommentsAndStrings } from "./_source-tools.ts";
import {
  addRecipients,
  extractAddress,
  isValidEmail,
  parseRecipientInput,
  recipientsToField,
} from "../components/customer/mail/recipients.ts";
import {
  imageStyleForPreset,
  imageWidthAttrForPreset,
  imageStyleForWidth,
} from "../components/customer/mail/compose-image-size.ts";
import { prepareComposedBody } from "../components/customer/mail/compose-html.ts";

// A 1x1 transparent PNG, used as a stand-in for a pasted image.
const PNG_B64 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==";

// ---------------------------------------------------------------------------
// Recipient chips: parsing / validation / dedupe. The send payload the server
// expects is a comma-separated string, so a chip list must round-trip to exactly
// the addresses that get sent.
// ---------------------------------------------------------------------------

test("isValidEmail accepts a plausible address and rejects a non-address", () => {
  assert.ok(isValidEmail("a@b.com"));
  assert.ok(isValidEmail("  spaced@example.co.uk  "));
  assert.ok(!isValidEmail("notanemail"));
  assert.ok(!isValidEmail("missing@domain"));
  assert.ok(!isValidEmail("@no-local.com"));
});

test("extractAddress pulls the bare address out of a Name <addr> token", () => {
  assert.equal(extractAddress("Ada Lovelace <ada@x.com>"), "ada@x.com");
  assert.equal(extractAddress("plain@x.com"), "plain@x.com");
});

test("parseRecipientInput splits a comma-separated list into valid chips", () => {
  const { valid, invalid } = parseRecipientInput("a@x.com, b@y.com,c@z.com");
  assert.deepEqual(valid, ["a@x.com", "b@y.com", "c@z.com"]);
  assert.deepEqual(invalid, []);
});

test("parseRecipientInput splits on spaces, semicolons and newlines too", () => {
  const { valid } = parseRecipientInput("a@x.com b@y.com;c@z.com\nd@w.com");
  assert.deepEqual(valid, ["a@x.com", "b@y.com", "c@z.com", "d@w.com"]);
});

test("parseRecipientInput de-duplicates case-insensitively, first casing wins", () => {
  const { valid } = parseRecipientInput("Bob@X.com, bob@x.com, BOB@x.COM");
  assert.deepEqual(valid, ["Bob@X.com"], "the same address is only chipped once");
});

test("parseRecipientInput keeps a Name <addr> piece whole and extracts the address", () => {
  const { valid, invalid } = parseRecipientInput("Ada Lovelace <ada@x.com>, Grace <grace@y.com>");
  assert.deepEqual(valid, ["ada@x.com", "grace@y.com"]);
  assert.deepEqual(invalid, [], "the display-name words are not treated as bad tokens");
});

test("parseRecipientInput reports invalid tokens instead of dropping them", () => {
  const { valid, invalid } = parseRecipientInput("good@x.com, nope, also-bad");
  assert.deepEqual(valid, ["good@x.com"]);
  assert.deepEqual(invalid, ["nope", "also-bad"]);
});

test("addRecipients merges into existing chips without duplicating", () => {
  const { chips, invalid } = addRecipients(["a@x.com"], "a@x.com, b@y.com, junk");
  assert.deepEqual(chips, ["a@x.com", "b@y.com"], "a@x.com is not added twice");
  assert.deepEqual(invalid, ["junk"]);
});

test("recipientsToField produces the comma-separated payload shape the server parses", () => {
  assert.equal(recipientsToField(["a@x.com", "b@y.com"]), "a@x.com, b@y.com");
  // And that string round-trips back to the same addresses via the server's split.
  const serverSplit = "a@x.com, b@y.com".split(/[,;]+/).map((s) => s.trim()).filter(Boolean);
  assert.deepEqual(serverSplit, ["a@x.com", "b@y.com"]);
});

// ---------------------------------------------------------------------------
// Inline image sizing: the chosen size must persist into the sent HTML and
// survive prepareComposedBody / safeHtml.
// ---------------------------------------------------------------------------

test("imageStyleForPreset maps presets to fixed px widths (and full to 100%)", () => {
  assert.match(imageStyleForPreset("small"), /width:\s*160px/);
  assert.match(imageStyleForPreset("medium"), /width:\s*320px/);
  assert.match(imageStyleForPreset("large"), /width:\s*480px/);
  assert.match(imageStyleForPreset("full"), /width:\s*100%/);
  // Every preset caps display width so a big image can't blow out a narrow pane.
  for (const p of ["small", "medium", "large", "full"] as const) {
    assert.match(imageStyleForPreset(p), /max-width:\s*100%/);
  }
});

test("imageWidthAttrForPreset gives a px width attr, or null for full", () => {
  assert.equal(imageWidthAttrForPreset("medium"), "320");
  assert.equal(imageWidthAttrForPreset("full"), null);
});

test("imageStyleForWidth clamps a drag width to a sane minimum", () => {
  assert.match(imageStyleForWidth(300), /width:\s*300px/);
  assert.match(imageStyleForWidth(5), /width:\s*24px/, "tiny drags are clamped up");
});

test("a preset-sized inline image keeps its width through prepareComposedBody", () => {
  const style = imageStyleForPreset("medium");
  const width = imageWidthAttrForPreset("medium")!;
  const src = `<img src="data:image/png;base64,${PNG_B64}" style="${style}" width="${width}">`;
  const { html, images } = prepareComposedBody(src);
  assert.equal(images.length, 1, "the image is still lifted to a cid attachment");
  assert.match(html, /src="cid:/, "src references the inline cid");
  assert.match(html, /width:\s*320px/, "the inline width STYLE survives sanitisation");
  assert.match(html, /width="320"/, "the width ATTRIBUTE survives sanitisation");
});

test("a full-width inline image keeps width:100% through prepareComposedBody", () => {
  const src = `<img src="data:image/png;base64,${PNG_B64}" style="${imageStyleForPreset("full")}">`;
  const { html } = prepareComposedBody(src);
  assert.match(html, /width:\s*100%/, "full-width style survives");
});

// ---------------------------------------------------------------------------
// SOURCE TRIPWIRES — a control whose outcome isn't verified must not ship. These
// prove the composer moved OUT of the mail page into the shell-level provider /
// portal (so it persists across navigation and its `fixed` position is the real
// viewport), and that the send still routes through the sanitising pipeline.
// ---------------------------------------------------------------------------

function readSrc(rel: string): string {
  return stripCommentsAndStrings(readFileSync(fileURLToPath(new URL(rel, import.meta.url)), "utf8"));
}

test("MailClient drives the composer through the provider, not an inline <Composer>", () => {
  const src = readSrc("../components/customer/mail/MailClient.tsx");
  assert.match(src, /useCompose\(\)/, "the mail client opens compose via the context");
  assert.match(src, /compose\.open\(/, "drafts are handed to the provider");
  assert.ok(!/<\s*Composer\b/.test(src), "the composer is NOT rendered inline in the mail page anymore");
});

test("ComposeProvider renders the Composer through a portal to <body>", () => {
  const src = readSrc("../components/customer/mail/ComposeProvider.tsx");
  assert.match(src, /createPortal\(/, "the composer must be portalled, not rendered in place");
  assert.match(src, /document\.body/, "portalled to <body> so `fixed` means the real viewport");
  assert.match(src, /<\s*Composer\b/, "the provider owns the Composer element");
});

test("ComposeProvider send still routes through the sanitising send action", () => {
  const src = readSrc("../components/customer/mail/ComposeProvider.tsx");
  assert.match(src, /sendMessage\(/, "the provider sends via the server action (which re-sanitises)");
});

test("the Composer still sanitises its body through prepareComposedBody before sending", () => {
  const src = readSrc("../components/customer/mail/Composer.tsx");
  assert.match(src, /prepareComposedBody\(/, "the composed HTML must be sanitised, never sent raw");
